        candidatos=(CandidatoCampo(unidad_compatible=False),),
    )

    assert resolucion == ResolucionCampo(
        codigo="marcador_laboratorio_alfa", estado="malformado"
    )
    assert "valor" not in repr(resolucion).lower()


